
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.123759707810319e-02, -6.106943193364277e-02, -6.081943523464803e-02, -6.044226726186015e-02, -5.986085909257840e-02, -5.893588001616967e-02, -5.739446903520023e-02, -5.464707655034861e-02, -4.928779289950742e-02, -3.803060730738560e-02, -1.978764425139690e-02, -3.041878198541903e-02, -3.272335250883576e-02, -2.788355931678015e-02, -1.666718015741042e-02, -6.537562605746974e-04, 6.199511473574099e-03, -7.015915400352749e-04, -7.132244177741644e-05, -1.745175130844257e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


